CREATE DATABASE IF NOT EXISTS ai_invoice_reconciliation CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE ai_invoice_reconciliation;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) NOT NULL UNIQUE,role VARCHAR(40) NOT NULL DEFAULT 'REVIEWER',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vendors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL UNIQUE,code VARCHAR(40) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE purchase_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,po_number VARCHAR(50) NOT NULL UNIQUE,vendor_id BIGINT UNSIGNED NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'OPEN',order_date DATE NOT NULL,total_amount DECIMAL(14,2) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vendor_id) REFERENCES vendors(id),INDEX(vendor_id,status));
CREATE TABLE purchase_order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,po_id BIGINT UNSIGNED NOT NULL,item_name VARCHAR(180) NOT NULL,ordered_quantity DECIMAL(12,2) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,FOREIGN KEY(po_id) REFERENCES purchase_orders(id),INDEX(po_id,item_name));
CREATE TABLE deliveries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,po_id BIGINT UNSIGNED NOT NULL,delivery_number VARCHAR(60) NOT NULL UNIQUE,delivery_date DATE NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'RECEIVED',grn_id BIGINT UNSIGNED NULL,FOREIGN KEY(po_id) REFERENCES purchase_orders(id),INDEX(po_id,delivery_date));
CREATE TABLE delivery_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,delivery_id BIGINT UNSIGNED NOT NULL,item_name VARCHAR(180) NOT NULL,delivered_quantity DECIMAL(12,2) NOT NULL,FOREIGN KEY(delivery_id) REFERENCES deliveries(id) ON DELETE CASCADE,INDEX(delivery_id,item_name));
CREATE TABLE grns(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,po_id BIGINT UNSIGNED NOT NULL,delivery_id BIGINT UNSIGNED NULL,grn_number VARCHAR(60) NOT NULL UNIQUE,grn_date DATE NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'ACCEPTED',inspection_notes TEXT NULL,FOREIGN KEY(po_id) REFERENCES purchase_orders(id),FOREIGN KEY(delivery_id) REFERENCES deliveries(id) ON DELETE SET NULL,UNIQUE KEY unique_po_grn (po_id),INDEX(po_id,delivery_id));
CREATE TABLE grn_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,grn_id BIGINT UNSIGNED NOT NULL,delivery_id BIGINT UNSIGNED NULL,item_name VARCHAR(180) NOT NULL,accepted_quantity DECIMAL(12,2) NOT NULL,FOREIGN KEY(grn_id) REFERENCES grns(id),FOREIGN KEY(delivery_id) REFERENCES deliveries(id) ON DELETE SET NULL,INDEX(grn_id,item_name));
CREATE TABLE processing_batches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_number VARCHAR(60) NOT NULL UNIQUE,total_count INT NOT NULL DEFAULT 0,processed_count INT NOT NULL DEFAULT 0,status VARCHAR(40) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_number VARCHAR(60) NOT NULL UNIQUE,vendor_id BIGINT UNSIGNED NOT NULL,po_number VARCHAR(50) NOT NULL,invoice_date DATE NOT NULL,tax_amount DECIMAL(14,2) NOT NULL DEFAULT 0,total_amount DECIMAL(14,2) NOT NULL,status VARCHAR(40) NOT NULL DEFAULT 'UPLOADED',source_file VARCHAR(255),batch_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(vendor_id) REFERENCES vendors(id),FOREIGN KEY(batch_id) REFERENCES processing_batches(id),INDEX(status,created_at),INDEX(po_number));
CREATE TABLE invoice_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,item_name VARCHAR(180) NOT NULL,quantity DECIMAL(12,2) NOT NULL,unit_price DECIMAL(14,2) NOT NULL,line_total DECIMAL(14,2) NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id),INDEX(invoice_id,item_name));
CREATE TABLE processing_results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NULL UNIQUE,batch_id BIGINT UNSIGNED NULL,po_id BIGINT UNSIGNED NULL,status VARCHAR(40) NOT NULL,result_json JSON NOT NULL,processed_at DATETIME NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id),FOREIGN KEY(batch_id) REFERENCES processing_batches(id),FOREIGN KEY(po_id) REFERENCES purchase_orders(id),INDEX(batch_id,status));
CREATE TABLE mismatch_exceptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,exception_type VARCHAR(60) NOT NULL,severity VARCHAR(30) NOT NULL,explanation TEXT NOT NULL,recommended_action TEXT NOT NULL,status VARCHAR(40) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(invoice_id) REFERENCES invoices(id),INDEX(status,created_at));
CREATE TABLE approvals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,reviewer VARCHAR(120) NOT NULL,decision VARCHAR(30) NOT NULL,comment TEXT,decided_at DATETIME NOT NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE agent_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,invoice_id BIGINT UNSIGNED NOT NULL,agent_name VARCHAR(120) NOT NULL,status VARCHAR(30) NOT NULL,result_json JSON NOT NULL,started_at DATETIME NOT NULL,completed_at DATETIME NULL,FOREIGN KEY(invoice_id) REFERENCES invoices(id),INDEX(invoice_id,id));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,action VARCHAR(80) NOT NULL,entity_type VARCHAR(60) NOT NULL,entity_id VARCHAR(60) NOT NULL,details TEXT,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(created_at));
CREATE TABLE returns(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,po_id BIGINT UNSIGNED NOT NULL,delivery_id BIGINT UNSIGNED NULL,return_number VARCHAR(60) NOT NULL UNIQUE,return_date DATE NOT NULL,item_name VARCHAR(180) NOT NULL,quantity DECIMAL(12,2) NOT NULL,reason TEXT NULL,status VARCHAR(40) NOT NULL DEFAULT 'RETURNED',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(po_id) REFERENCES purchase_orders(id),INDEX(po_id));
